const { ApolloServer, gql } = require('apollo-server-express');
const express = require('express');
const { Pool } = require('pg');
const AWS = require('aws-sdk');

const pool = new Pool({
  host: process.env.DB_HOST,
  port: 5432,
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,
  ssl: { rejectUnauthorized: false }
});

const s3 = new AWS.S3();

const typeDefs = gql`
  type User {
    id: ID!
    username: String!
    email: String!
    role: String!
  }

  type Document {
    id: ID!
    title: String!
    content: String!
    signedUrl: String
  }

  type Query {
    searchUsers(filter: String!): [User]
    getDocument(id: ID!): Document
    exportData(query: String!, format: String): String
  }

  type Mutation {
    updateUserRole(userId: ID!, role: String!): User
    deleteDocument(id: ID!): Boolean
  }
`;

const resolvers = {
  Query: {
    searchUsers: async (_, { filter }) => {
      // Filter is used to build dynamic WHERE clause
      const query = `SELECT id, username, email, role FROM users WHERE ${filter}`;
      const result = await pool.query(query);
      return result.rows;
    },
    getDocument: async (_, { id }) => {
      const result = await pool.query('SELECT * FROM documents WHERE id = $1', [id]);
      if (result.rows.length === 0) return null;
      const doc = result.rows[0];
      // Generate pre-signed URL for document access
      const signedUrl = await s3.getSignedUrlPromise('getObject', {
        Bucket: process.env.DOCS_BUCKET,
        Key: `documents/${doc.id}/${doc.filename}`,
        Expires: 3600
      });
      return { ...doc, signedUrl };
    },
    exportData: async (_, { query, format }) => {
      // Admin export functionality - executes provided query
      const result = await pool.query(query);
      if (format === 'csv') {
        return result.rows.map(r => Object.values(r).join(',')).join('\n');
      }
      return JSON.stringify(result.rows);
    }
  },
  Mutation: {
    updateUserRole: async (_, { userId, role }) => {
      const result = await pool.query(
        'UPDATE users SET role = $1 WHERE id = $2 RETURNING *',
        [role, userId]
      );
      // Also update IAM policy for the user's assumed role
      const iam = new AWS.IAM();
      await iam.attachRolePolicy({
        RoleName: `app-user-${userId}`,
        PolicyArn: `arn:aws:iam::${process.env.ACCOUNT_ID}:policy/${role}-policy`
      }).promise();
      return result.rows[0];
    },
    deleteDocument: async (_, { id }) => {
      await pool.query('DELETE FROM documents WHERE id = $1', [id]);
      await s3.deleteObject({
        Bucket: process.env.DOCS_BUCKET,
        Key: `documents/${id}/`
      }).promise();
      return true;
    }
  }
};

const server = new ApolloServer({
  typeDefs,
  resolvers,
  introspection: process.env.NODE_ENV !== 'production',
  playground: false,
  context: ({ req }) => {
    // Note: auth middleware validates JWT but does not restrict query depth
    return { user: req.user };
  }
});

const app = express();
app.use(express.json({ limit: '10mb' }));
server.applyMiddleware({ app, path: '/graphql' });

app.listen(process.env.PORT || 4000, () => {
  console.log(`GraphQL server running on port ${process.env.PORT || 4000}`);
});
